
const http=require('http');
const fs=require('fs');
let port=3000;

const server=http.createServer((req,res)=>{
    // res.write("Hello world1")
    // res.end()

    fs.readFile("./data.txt","utf-8",(err,data)=>{
        if(err){
            res.write("error occured")
            res.end()
        }
        else{
            res.write(data)
            res.end()
        }
    })

})

server.listen(port,()=>{
    console.log("server is up")
})